import 'package:flutter/material.dart'; import '../repositories/app_repo.dart';
class MasterScreen extends StatefulWidget{final String title,table;final List<String> fields;const MasterScreen({super.key,required this.title,required this.table,required this.fields});@override State<MasterScreen> createState()=>_MasterScreenState();}
class _MasterScreenState extends State<MasterScreen>{final repo=AppRepo();String q='';Future<List<Map<String,Object?>>> get data async=>repo.rows(widget.table,order:'id DESC');String label(String f)=>f.replaceAll('_',' ').replaceFirst(RegExp(r'^.'),(m)=>m.group(0)!.toUpperCase());
void form([Map<String,Object?>? old]){final ctr={for(final f in widget.fields)f:TextEditingController(text:'${old?[f]??''}')};showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(c).viewInsets.bottom),child:SingleChildScrollView(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(widget.title,style:Theme.of(c).textTheme.titleLarge),...widget.fields.map((f)=>Padding(padding:const EdgeInsets.only(top:10),child:TextField(controller:ctr[f],keyboardType:f.contains('amount')||f=='rate'?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:label(f),border:const OutlineInputBorder())))),const SizedBox(height:14),FilledButton(onPressed:()async{final m={for(final f in widget.fields)f:ctr[f]!.text}; if(old==null)await repo.insert(widget.table,m);else await repo.update(widget.table,m,'id=?',[old['id']]);if(mounted){Navigator.pop(c);setState((){});}},child:const Text('Save'))]))));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.title)),body:FutureBuilder(future:data,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final list=s.data!;final filtered=list.where((r)=>q.isEmpty||r.values.any((v)=>'$v'.toLowerCase().contains(q.toLowerCase()))).toList();return Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search',border:OutlineInputBorder()))),Expanded(child:ListView.builder(itemCount:filtered.length,itemBuilder:(c,i){final r=filtered[i];final title=r[widget.fields.first]??r['id'];return Card(child:ListTile(title:Text('$title'),subtitle:Text(widget.fields.skip(1).take(3).map((f)=>'${label(f)}: ${r[f]??''}').join('  •  ')),trailing:PopupMenuButton(itemBuilder:(_)=>[const PopupMenuItem(value:'e',child:Text('Edit')),const PopupMenuItem(value:'d',child:Text('Delete'))],onSelected:(v)async{if(v=='e')form(r);else{await repo.delete(widget.table,r['id'] as int);setState((){});}}));}))])}),floatingActionButton:FloatingActionButton(onPressed:()=>form(),child:const Icon(Icons.add)));}
}
